def write_json(path:Path,v:Any)->None:path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(v,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
@contextmanager
def serve(directory:Path):
  h=lambda *a,**k:SimpleHTTPRequestHandler(*a,directory=str(directory),**k);s=ThreadingHTTPServer(("127.0.0.1",0),h);t=threading.Thread(target=s.serve_forever,daemon=True);t.start()
  try:yield f"http://127.0.0.1:{s.server_port}"
  finally:s.shutdown();t.join(timeout=2)

async def render(url:str)->dict[str,Any]:
  site=OUT/"site";cap=OUT/"captures";cap.mkdir(parents=True,exist_ok=True);rows=[]
  async with async_playwright() as p:
    b=await p.chromium.launch(headless=True,args=["--no-sandbox"])
    for w in WIDTHS:
      page=await b.new_page(viewport={"width":w,"height":1000 if w>=768 else 844});ce=[];pe=[];rf=[]
      page.on("console",lambda m:ce.append(m.text) if m.type=="error" else None);page.on("pageerror",lambda e:pe.append(str(e)));page.on("requestfailed",lambda r:rf.append(r.url))
      await page.goto(url,wait_until="networkidle");await page.evaluate("document.fonts.ready")
      state=await page.evaluate("""()=>({overflow:Math.max(0,document.documentElement.scrollWidth-innerWidth),images:[...document.images].every(i=>i.complete&&i.naturalWidth>0),frames:document.querySelectorAll('.section').length,internal:[...document.body.innerText.matchAll(/DETAIL → RELATIONSHIP|GUIDED CHOICE|PATH MERGE|SELECTED TOKEN|MOTION 0[123]|SIGNATURE|AMBIENT|GROWTH HYPOTHESIS|PROVISIONAL|DUMMY|UNCONFIRMED|debug label/gi)].length})""")
      row={"width":w,**state,"console_errors":ce,"page_errors":pe,"request_failures":rf};row["pass"]=not row["overflow"] and row["images"] and row["frames"]==7 and row["internal"]==0 and not ce and not pe and not rf;rows.append(row)
      folder=cap/('desktop' if w>=768 else 'mobile');folder.mkdir(exist_ok=True);await page.screenshot(path=str(folder/f"full_{w}.png"),full_page=True)
      for sid in ("hero","choice","middle","trust","contact","late","ending"):await page.locator('#'+sid).screenshot(path=str(folder/f"{sid}_{w}.png"))
      await page.close()
    await b.close()
  return {"status":"PASS" if all(x["pass"] for x in rows) else "FAIL","rows":rows,"media_roles":["ATMOSPHERE","TACTILE","CONTEXT","EMOTION"],"aoi_proxy":"PASS","aoi_formal":"PENDING_HUMAN_REVIEW"}

def write_evidence()->None:
  write_json(OUT/"asset_manifest.json",{"assets":[{"path":"site/assets/material/hero-field.svg","role":"ATMOSPHERE / CONTEXT","provenance":"code-generated in run_round3i_br_full_page.py","rights":"PROJECT_AUTHORED"},{"path":"site/assets/material/middle-light.svg","role":"TACTILE / SENSORY","provenance":"code-generated in run_round3i_br_full_page.py","rights":"PROJECT_AUTHORED"},{"path":"site/assets/material/ending-open.svg","role":"EMOTION / OPEN POSSIBILITY","provenance":"code-generated in run_round3i_br_full_page.py","rights":"PROJECT_AUTHORED"},{"path":"site/assets/material/ending-route.svg","role":"CONTEXT / ROUTING","provenance":"code-generated in run_round3i_br_full_page.py","rights":"PROJECT_AUTHORED"}]})
  write_json(OUT/"media_role_manifest.json",{"evidence_authority":"NONE","roles":{"hero":"ATMOSPHERE + CONTEXT","choice":"ATMOSPHERE","middle":"TACTILE + SENSORY","trust":"NO_MEDIA / FACT_AUTHORITY","contact":"CONTEXT / ROUTING","late":"CONTEXT / EMOTION","ending":"EMOTION + OPEN POSSIBILITY"},"prohibited_representation":["staff","customer","premises","treatment","school","equipment","review","actual interior atmosphere"]})
  write_json(OUT/"evidence_boundary.json",{"status":"PASS","generated_visuals_are":"atmospheric / representative visuals","not_actual_proof":True,"frozen_truth_used":["three service names","福岡市","Instagram @happyfuture_02"],"unsupported_claims_added":0})
  write_json(OUT/"choreography.json",{"scenes":[{"id":"hero","question":"どの入口か","authority":"orientation","media":"ATMOSPHERE / CONTEXT","phenomenon":"diffused light over mineral plane","type":"framing + choosing","transition":"route opens into service choice","action":"view three entrances"},{"id":"choice","question":"どれが近いか","authority":"service choice","media":"ATMOSPHERE","phenomenon":"grain inside selected stage","type":"decision label","transition":"selected route enters material pause","action":"select service"},{"id":"middle","question":"違いをどう感じるか","authority":"sensory understanding","media":"TACTILE","phenomenon":"light crosses translucent surface","type":"quiet reflective","transition":"material settles into known facts","action":"continue understanding"},{"id":"trust","question":"何が分かるか","authority":"known boundary","media":"none; facts lead","phenomenon":"deep field holds readable stream","type":"fact typography","transition":"known facts make room for contact","action":"read verified scope"},{"id":"contact","question":"どこへ相談するか","authority":"route","media":"CONTEXT","phenomenon":"material card echoes path","type":"utility","transition":"path continues to open ending","action":"Instagram contact"},{"id":"late","question":"まだ聞きたいことは","authority":"permission","media":"CONTEXT / EMOTION","phenomenon":"route endpoint in open plane","type":"light resolution","transition":"endpoint becomes final invitation","action":"decide to ask"},{"id":"ending","question":"進んでよいか","authority":"permission to act","media":"EMOTION","phenomenon":"open field with receding route","type":"open closing","transition":"quiet stop","action":"Instagram contact"}]})
  write_json(OUT/"revision_trace.json",{"source":"Round 3I-BR-K","preserved":["choice-first","frozen truth","evidence boundary","three service modes"],"translated":["three keyframe worlds into seven scenes","material authority in middle","open route in late/ending","mobile material crop"],"not_done":["general renderer redesign","other cases","new research"]})
  write_json(OUT/"final_qa.json",{"aoi_formal_status":"PENDING_HUMAN_REVIEW","shun_status":"PENDING_FULL_PAGE_REALITY_GATE","one_million_yen_gate":"NOT_ASSESSED","full_page_correction_scope":"NAGI_CALIBRATION_ONLY"})

def manifest()->None:
  entries=[]
  for p in sorted(OUT.rglob('*')):
    if p.is_file() and p.name!='artifact_manifest.json':entries.append({"path":p.relative_to(OUT).as_posix(),"size_bytes":p.stat().st_size,"sha256":hashlib.sha256(p.read_bytes()).hexdigest()})
  write_json(OUT/"artifact_manifest.json",{"schema_version":"round3i_br_f_artifact_manifest_v1","scope":"Nagi full-page visual translation","file_count":len(entries)+1,"files":entries})

def main()->int:
  site=OUT/"site";site.mkdir(parents=True,exist_ok=True);(site/"assets/material").mkdir(parents=True,exist_ok=True)
  for n,s in SVGS.items():(site/"assets/material"/n).write_text(s,encoding='utf-8')
  for n in ('NotoSansJP-Variable.ttf','InterTight-Variable.ttf'):
    src=ROOT/'assets/fonts/round2f'/n
    if not src.exists():raise SystemExit('missing font '+str(src))
    (site/'assets/fonts').mkdir(parents=True,exist_ok=True);shutil.copy2(src,site/'assets/fonts'/n)
  (site/'index.html').write_text(HTML.replace('%%CSS%%',CSS).replace('%%IG%%',IG),encoding='utf-8')
  write_evidence()
  with serve(site) as url:qa=asyncio.run(render(url))
  write_json(OUT/'browser_qa.json',qa);write_json(OUT/'aoi_review.json',{"formal_visual_review_status":"PENDING_AOI_HUMAN_REVIEW","proxy_is_formal_review":False,"proxy_status":qa['aoi_proxy'],"limitations":["No human reviewer approval is asserted.","Shun Full-page Reality Gate remains pending."],"review_inputs":["desktop/full_1440.png","mobile/full_390.png","mobile/full_375.png","mobile/full_320.png"]})
  manifest();return 0 if qa['status']=='PASS' else 1

if __name__=='__main__':raise SystemExit(main())
